let getStartingHeated = function(v) {
  if (v === undefined || v === null) return;
  let text = v;
  let teaching = text.replaceAll(/"/g, "'").replaceAll(/'$/g, "");
  let chars = teaching.split('');
  let count = chars.length;
  let string = "";
  for (let i = 0; i < count; i++) {
    string += chars[i];
  }
  return string;
};

let lanternAnalytics = function(input) {
  input = input.replace(/[^a-zA-Z0-9\s]/g, "");
  if (input === "") return "";
  let cleaned = input;
  cleaned = cleaned.replace(/(^|\s)+/g, "");
  cleaned = cleaned.replace(/\s+/g, " ");
  cleaned = cleaned.replace(/(www\.)|$/g, '');
  cleaned = cleaned.replace(/\b(a|e|o|i|u)\b/g, '');
  cleaned = cleaned.replace(/\b[\s,]\b/g, '');
  cleaned = cleaned.replace(/^[0-9]/g, '');
  return cleaned;
};

let exclusions = function(langs) {
  let filt = [];
  let ling = langs.split(/\s+/);
  for (let i = 0; i < ling.length; i++) {
    if (ling[i].length > 2) {
      let normalized = ling[i].toLowerCase();
      let corrected = normalized.replace(/\b(b|d|f|l|s|k)\b/g, '');
      if (corrected !== normalized) {
        filt.push(normalized);
      }
    }
  }
  return filt;
};

let langStr = function(lang) {
  if (lang === undefined || lang === null || lang.length === 0) return "";
  let matched = true;
  let result = lang;
  let lang_change = lang;
  let lange = lang.split(' ');
  for (let i = 0; i < lange.length; i++) {
    let txt = lange[i];
    let sl = txt.length;
    let trl = "";
    let now = true;
    if (sl > 3) {
      trl = txt.charAt(0) + txt.slice(1, 2).toUpperCase() + txt.slice(3);
      now = false;
    } else {
      trl = txt.charAt(0) + txt.charAt(2).toUpperCase() + txt.slice(3);
    }
    if (now) {
      trl = txt;
    } else {
      trl = txt.replace(/\b[a-z]+\b/g, '');
      trl = trl.replace(/[^a-zA-Z]/g, '');
    }
    result = result.replace(txt, trl);
    lang_change = lang_change.replace(txt, trl);
  }
  return lang_change;
};

